function updateOfflineBanner(){const banner=document.getElementById(`offlineBanner`);if(!banner)return;const pending=offlineQueue.length;const parts=[];if(isOfflineMode)parts.push(`Hors ligne`);if(pending)parts.push(`${pending} action${pending>1?`s`:``} à envoyer`);banner.textContent=parts.join(` · `);banner.style.display=parts.length?``:`none`}function tellServiceWorkerNetwork(){const sw=navigator.serviceWorker&&navigator.serviceWorker.controller;if(sw)sw.postMessage({kinetOffline:isOfflineMode})}function onOfflineChange(){loadOfflineQueue();updateOfflineBanner();tellServiceWorkerNetwork()}function blockIfOffline(){if(!isOfflineMode)return false;showToast(`Hors ligne, reconnecte-toi pour ça`);return true}async function completeOfflineCreation({table,row,saved}){if(!saved||!row.tmdb_id)return;try{if(table===`tv_shows`){const d=await fetchTvDetails(row.tmdb_id);await supabaseClient.from(`tv_shows`).update({overview:d.overview||null,status:d.status||null,in_production:!!d.in_production,number_of_seasons:d.number_of_seasons||null,number_of_episodes:d.number_of_episodes||null}).eq(`id`,saved.id)}else if(table===`films`||table===`watchlist`){generateTcgCardsForFilm(row.tmdb_id);if(saved.overview)return;const d=await fetchMovieDetails(row.tmdb_id);const fields={overview:d.overview||null};if(table===`watchlist`)fields.release_date=d.release_date||null;await supabaseClient.from(table).update(fields).eq(`id`,saved.id)}}catch(e){console.error(e)}}async function syncOfflineWrites(){loadOfflineQueue();updateOfflineBanner();if(isOfflineMode)return null;const result=await replayOfflineQueue();updateOfflineBanner();if(!result)return null;if(result.sent)showToast(`${result.sent} action${result.sent>1?`s`:``} envoyée${result.sent>1?`s`:``}`);if(result.refused)showToast(`${result.refused} action${result.refused>1?`s`:``} refusée${result.refused>1?`s`:``} par le serveur`);result.created.forEach(c=>{completeOfflineCreation(c)});return result}function offlineRouteAfterSync(hash,idMap){const m=hash.match(/^#\/series\/(-\d{13,})/);return m&&idMap[m[1]]!=null?`#/series/${idMap[m[1]]}`:hash}async function onBackOnline(){updateOfflineBanner();tellServiceWorkerNetwork();if(!currentUser)return;const stale=servedFromDevice;servedFromDevice=false;const result=await syncOfflineWrites();if(!result&&!stale)return;await Promise.all([loadFilms(),loadViewings(),loadWatchlist(),loadTrackedShows()]);const route=offlineRouteAfterSync(location.hash,result?result.idMap:{});if(route!==location.hash)location.hash=route;render();renderRoute();if(!result)showToast(`De retour en ligne`)}const OFFLINE_SKELETON_WAIT_MS=1500;function settleOfflineSkeletonsSoon(){if(!isOfflineMode)return;setTimeout(()=>{document.querySelectorAll(`.skeleton-row:first-child`).forEach(row=>{row.parentElement.innerHTML=`<div class="tmdb-empty">Disponible au retour du réseau.</div>`})},OFFLINE_SKELETON_WAIT_MS)}document.addEventListener(`error`,e=>{if(isOfflineMode&&e.target&&e.target.tagName===`IMG`)e.target.style.visibility=`hidden`},true);try{Object.keys(localStorage).filter(k=>k.startsWith(`offlineCache_`)).forEach(k=>localStorage.removeItem(k))}catch(e){}if(`serviceWorker`in navigator){window.addEventListener(`load`,()=>{navigator.serviceWorker.register(`sw.js`).then(reg=>watchForUpdate(reg)).catch(err=>console.error(`Échec de l'enregistrement du service worker`,err));navigator.serviceWorker.ready.then(tellServiceWorkerNetwork)})}let updateReloadArmed=false;function showUpdateBanner(reg){const el=document.getElementById(`updateBanner`);if(!el||el.style.display===`flex`)return;el.style.display=`flex`;document.getElementById(`updateBannerBtn`).onclick=()=>{if(reg.waiting)reg.waiting.postMessage(`skipWaiting`);else location.reload()}}function watchForUpdate(reg){if(reg.waiting&&navigator.serviceWorker.controller)showUpdateBanner(reg);reg.addEventListener(`updatefound`,()=>{const installing=reg.installing;if(!installing)return;installing.addEventListener(`statechange`,()=>{if(installing.state===`installed`&&navigator.serviceWorker.controller){showUpdateBanner(reg)}})});document.addEventListener(`visibilitychange`,()=>{if(document.visibilityState===`visible`)reg.update().catch(()=>{})});navigator.serviceWorker.addEventListener(`controllerchange`,()=>{if(updateReloadArmed)return;updateReloadArmed=true;location.reload()})}